393: /// Maps a format version and numerical record type identifier to its FeaturePoint ID.
394: ///
395: /// Returns FeaturePoint domain identifier (1..=14), or 0 for unencrypted auxiliary types.
396: /// FeaturePoint 8 designates plaintext bypass (`KeyStorage` 56, `FlightRecordRecover` 50).
397: #[must_use]
398: pub fn get_feature_point(version: u8, record_type: u8) -> u8 {
399:     if version == 13 {
400:         match record_type {
401:             50 | 56 => 8, // PlainText_8 bypass
402:             42 | 57 => 0, // Unencrypted
403:             5 | 9 | 10 | 20 | 24 | 30 | 54 => 7, // DJIFlyCustom_7
404:             12 | 16 | 19 | 22 | 26 | 27 | 28 | 51 | 52 | 55 => 6, // AfterSales_6
405:             49 => 5, // AirLink_5
406:             21 | 41 | 43 | 44 | 45 | 46 | 47 | 48 => 4, // Agriculture_4
407:             31 | 32 | 34 | 35 | 36 | 38 | 39 => 3, // Waypoint_3
408:             17 | 18 => 2, // Vision_2
409:             53 => 9, // FlightHub_9
410:             _ => 1, // Base_1
411:         }
412:     } else {
413:         // Version 14 (Granular domain isolation)
414:         match record_type {
415:             50 | 55 | 56 | 209 | 218 | 226 => 8, // PlainText_8 bypass
416:             42 => 0, // Unencrypted
417:             3 => 10, // Gimbal_10
418:             4 | 11 | 29 | 33 | 62 => 11, // RC_11
419:             25 => 12, // Camera_12
420:             7 | 8 | 22 => 13, // Battery_13
421:             28 | 51 | 52 => 14, // FlySafe_14
422:             5 | 9 | 10 | 20 | 24 | 30 | 54 | 253 | 254 => 7, // DJIFlyCustom_7
423:             12 | 16 | 19 | 26 | 27 => 6, // AfterSales_6
424:             49 | 57 => 5, // AirLink_5
425:             21 | 41 | 43 | 44 | 45 | 46 | 47 | 48 => 4, // Agriculture_4
426:             31 | 32 | 34 | 35 | 36 | 38 | 39 | 60 => 3, // Waypoint_3
427:             17 | 18 | 61 => 2, // Vision_2
428:             53 => 9, // FlightHub_9
429:             _ => 1, // Base_1
430:         }
431:     }
432: }
