434: /// Streaming zero-allocation iterator over DJI `.txt` binary flight records.
435: ///
436: /// Tracks stream byte offsets, version capabilities, and details summary partitions
437: /// to demux sequential telemetry envelopes until reaching stream boundary or EOF.
438: #[derive(Debug, Clone)]
439: pub struct RecordEnvelopeIterator<'a> {
440:     buffer: &'a [u8],
441:     current_offset: usize,
442:     end_offset: usize,
443:     capabilities: VersionCapabilities,
444:     header_offset: usize,
445:     resync: bool,
446:     aes_engine: Option<AesContinuousIvEngine>,
447: }
448: 
449: impl<'a> RecordEnvelopeIterator<'a> {
450:     /// Constructs a new `RecordEnvelopeIterator` from a flight log buffer and parsed header.
451:     ///
452:     /// # Stream Boundary Resolution
453:     /// - **v1–v11** (`DetailsLocation::EndOfFile`): Telemetry records reside from `header_length`
454:     ///   (100 bytes) up to `details_offset`.
455:     /// - **v12–v14** (`DetailsLocation::HeaderOffset`): Summary details reside between `header_length`
456:     ///   and `details_offset`, and telemetry records begin at `details_offset` running to EOF (`buffer.len()`).
457:     ///
458:     /// # Errors
459:     /// Returns [`FlightReaderError::CorruptedHeader`] if `details_offset` is negative.
460:     /// Returns [`FlightReaderError::UnsupportedVersion`] if header version is unhandled.
461:     pub fn new(buffer: &'a [u8], header: &TxtHeader) -> Result<Self> {
462:         let capabilities = header.capabilities()?;
463:         let header_offset = header.header_length as usize;
464: 
465:         let (current_offset, end_offset) = match capabilities.details_location {
466:             DetailsLocation::EndOfFile => {
467:                 let end = if header.details_offset >= 0 {
468:                     (header.details_offset as usize).min(buffer.len())
469:                 } else {
470:                     return Err(FlightReaderError::CorruptedHeader);
471:                 };
472:                 let start = header_offset.min(end);
473:                 (start, end)
474:             }
475:             DetailsLocation::HeaderOffset => {
476:                 let start = if header.details_offset >= 0 {
477:                     (header.details_offset as usize).min(buffer.len())
478:                 } else {
479:                     return Err(FlightReaderError::CorruptedHeader);
480:                 };
481:                 (start, buffer.len())
482:             }
483:         };
484: 
485:         Ok(Self {
486:             buffer,
487:             current_offset,
488:             end_offset,
489:             capabilities,
490:             header_offset,
491:             resync: true,
492:             aes_engine: None,
493:         })
494:     }
495: 
496:     /// Alias for [`Self::new`] for explicit naming.
497:     #[inline]
498:     pub fn from_header(buffer: &'a [u8], header: &TxtHeader) -> Result<Self> {
499:         Self::new(buffer, header)
500:     }
