615:     /// Returns unconsumed slice of the record stream partition.
616:     #[inline]
617:     pub fn remaining(&self) -> &'a [u8] {
618:         if self.current_offset >= self.end_offset || self.current_offset >= self.buffer.len() {
619:             &[]
620:         } else {
621:             &self.buffer[self.current_offset..self.end_offset.min(self.buffer.len())]
622:         }
623:     }
