626: impl<'a> Iterator for RecordEnvelopeIterator<'a> {
627:     type Item = Result<RawRecordEnvelope<'a>>;
628: 
629:     fn next(&mut self) -> Option<Self::Item> {
630:         let record_len_width = self.capabilities.record_len_width;
631:         let header_size = 1 + record_len_width;
632: 
633:         while self.current_offset < self.end_offset {
634:             // In resilient mode, skip stray delimiters between records
635:             if self.resync && self.buffer[self.current_offset] == RECORD_DELIMITER {
636:                 self.current_offset += 1;
637:                 continue;
638:             }
639: 
640:             // Check if remaining slice can hold at least a record header
641:             let remaining = self.end_offset - self.current_offset;
642:             if remaining < header_size {
643:                 // Trailing padding bytes before EOF or Details block
644:                 self.current_offset = self.end_offset;
645:                 return None;
646:             }
647: 
648:             let slice = &self.buffer[self.current_offset..self.end_offset];
649:             match RawRecordEnvelope::parse(slice, record_len_width) {
650:                 Ok((envelope, total_len)) => {
651:                     self.current_offset += total_len;
652:                     return Some(Ok(envelope));
653:                 }
654:                 Err(err) => {
655:                     if !self.resync {
656:                         // Strict mode: advance cursor so caller can inspect or abort
657:                         self.current_offset = match err {
658:                             FlightReaderError::InvalidRecordDelimiter { .. } => {
659:                                 self.current_offset + 1
660:                             }
661:                             _ => self.end_offset,
662:                         };
663:                         return Some(Err(err));
664:                     }
665: 
666:                     // Resilient mode: scan forward byte-by-byte (cursor += 1)
667:                     self.current_offset += 1;
668:                 }
669:             }
670:         }
671: 
672:         None
673:     }
674: }
