106: /// Decoded Home Point telemetry record (Record Type 2).
107: ///
108: /// Encapsulates calibrated takeoff coordinates, ground reference elevation,
109: /// Return-To-Home cruise altitude, status flags, and the critical
110: /// `HomeDataRecorderFileIndex` linking pointer.
111: #[derive(Debug, Clone, Copy, PartialEq)]
112: pub struct HomeRecord {
113:     /// WGS84 Home Point Longitude in decimal degrees ($-180.0^\circ \dots +180.0^\circ$).
114:     pub longitude_deg: f64,
115:     /// WGS84 Home Point Latitude in decimal degrees ($-90.0^\circ \dots +90.0^\circ$).
116:     pub latitude_deg: f64,
117:     /// Raw WGS84 Home Point Longitude in radians.
118:     pub longitude_rad: f64,
119:     /// Raw WGS84 Home Point Latitude in radians.
120:     pub latitude_rad: f64,
121:     /// Ground reference barometric altitude at Home Point in meters.
122:     pub height_m: f32,
123:     /// Status and calibration flags (Bytes 20..22).
124:     pub status: HomeStatusFlags,
125:     /// Configured Return-To-Home cruise failsafe altitude in meters.
126:     pub go_home_height_m: u16,
127:     /// Reference heading angle for Course Lock flight mode in decimal degrees.
128:     pub course_lock_angle_deg: f64,
129:     /// On-board hardware blackbox recording sequence index (`FLY{index:03}.DAT`).
130:     pub data_recorder_file_index: u16,
131:     /// Critical battery auto forced-landing descent altitude in meters.
132:     pub force_landing_height_m: u8,
133: }
134: 
135: impl HomeRecord {
136:     /// Parses a Home Point telemetry payload from a borrowed byte slice.
137:     ///
138:     /// # Errors
139:     /// Returns [`FlightReaderError::MalformedPayload`] if `payload.len() < 46`.
140:     pub fn parse(payload: &[u8]) -> Result<Self> {
141:         if payload.len() < MIN_HOME_PAYLOAD_LEN {
142:             return Err(FlightReaderError::MalformedPayload {
143:                 record_type: RECORD_TYPE,
144:                 reason: "Home payload shorter than 46 bytes",
145:             });
146:         }
147: 
148:         let lon_rad = LittleEndian::read_f64(&payload[0..8]);
149:         let lat_rad = LittleEndian::read_f64(&payload[8..16]);
150:         let height_raw = LittleEndian::read_f32(&payload[16..20]);
151:         let status_raw = LittleEndian::read_u16(&payload[20..22]);
152:         let go_home_height_m = LittleEndian::read_u16(&payload[22..24]);
153:         let course_lock_raw = LittleEndian::read_i16(&payload[24..26]);
154:         let data_recorder_file_index = LittleEndian::read_u16(&payload[30..32]);
155:         let force_landing_height_m = payload[45];
156: 
157:         Ok(Self {
158:             longitude_deg: lon_rad * RAD_TO_DEG,
159:             latitude_deg: lat_rad * RAD_TO_DEG,
160:             longitude_rad: lon_rad,
161:             latitude_rad: lat_rad,
162:             height_m: height_raw / 10.0,
163:             status: HomeStatusFlags::new(status_raw),
164:             go_home_height_m,
165:             course_lock_angle_deg: course_lock_raw as f64 / 10.0,
166:             data_recorder_file_index,
167:             force_landing_height_m,
168:         })
169:     }
170: 
171:     /// Returns correlated on-board blackbox filename (e.g. `FLY142.DAT`), or `None` if index is 0.
172:     pub fn dat_file_name(&self) -> Option<String> {
173:         if self.data_recorder_file_index > 0 {
174:             Some(format!("FLY{:03}.DAT", self.data_recorder_file_index))
175:         } else {
176:             None
177:         }
178:     }
179: 
180:     /// Latitude encoded as signed 32-bit integer multiplied by $10^7$.
181:     #[inline]
182:     pub fn latitude_1e7(&self) -> i32 {
183:         (self.latitude_deg * 10_000_000.0).round() as i32
184:     }
185: 
186:     /// Longitude encoded as signed 32-bit integer multiplied by $10^7$.
187:     #[inline]
188:     pub fn longitude_1e7(&self) -> i32 {
189:         (self.longitude_deg * 10_000_000.0).round() as i32
190:     }
