192:     /// Validates whether geodetic coordinates represent a valid non-zero location.
193:     #[inline]
194:     pub fn is_valid_coordinates(&self) -> bool {
195:         self.latitude_deg >= -90.0
196:             && self.latitude_deg <= 90.0
197:             && self.longitude_deg >= -180.0
198:             && self.longitude_deg <= 180.0
199:             && (self.latitude_deg != 0.0 || self.longitude_deg != 0.0)
200:             && !self.latitude_deg.is_nan()
201:             && !self.longitude_deg.is_nan()
202:     }
203: }
